from django.db import models
from django.db.models import Case, When, Value, F, Q

class SomeModel(models.Model):
    data = models.JSONField()

def update_jsonfield_case_when(instance):
    # Constructing the Case/When expression to be used
    case_expression = Case(
        When(some_field=SomeValue, then=Value('something')),
        default=Value('default')
    )

    # Perform the update using update() to ensure the expression is evaluated in the database
    SomeModel.objects.filter(pk=instance.pk).update(
        data={F('data'), 'key': case_expression}
    )

    # Refresh the instance to get updated data
    instance.refresh_from_db()

# Example test usage
def test_update_jsonfield_case_when_key_is_null():
    obj = SomeModel.objects.create(data={'key': None})

    # Update JSONField using Case/When logic
    update_jsonfield_case_when(obj)

    # Assert the expected outcome
    assert obj.data == {"key": "something"}
